import { z } from 'zod';
import fs from 'fs';
import { requestServer, type AttachedServer } from './client';
import { isNewerVersion, serverVersionInfo } from './serverVersion';
import { waitForServerShutdown } from './serverShutdown';
import {
  stopRuntimeProcess,
  runtimeProcessIdentity,
} from '../services/stopRuntimeProcess';
import { classifyRuntimeActivity } from '../services/runtimeActivity';
import {
  recordRuntimeInterruption,
  type RuntimeInterruption,
} from './runtimeInterruption';
import type { CliIO } from './io';
import { errorMessage } from '../utils/errorMessage';

type RuntimeUpgradeOutcome =
  | { outcome: 'attach' }
  | { outcome: 'failed'; message: string; reason: string }
  | {
      outcome: 'spawn';
      restartArgs?: string[];
      interruptedWork?: RuntimeInterruption;
    };

const healthSchema = z.object({
  pid: z.number().int().positive(),
  rivetVersion: z.string().optional(),
  projectPath: z.string(),
  framework: z.string().optional(),
});
const upgradeSchema = z.object({
  stopping: z.boolean().optional(),
  reason: z.string().optional(),
  error: z.string().optional(),
  restartArgs: z.array(z.string()).optional(),
});
const devServerSchema = z.object({
  devServerHealth: z
    .object({ ownership: z.string(), port: z.number().nullable() })
    .optional(),
});
const INTERRUPTIBLE_REASONS = new Set([
  'active_work',
  'unknown_execution_state',
]);

type RuntimeRetirement =
  { outcome: 'retired'; restartArgs?: string[] } | { outcome: 'kept' };

const awaitOwnedRuntimeShutdown = async ({
  attached,
  processIdentity,
  shutdownTimeoutMs,
}: {
  attached: AttachedServer;
  processIdentity: string | null;
  shutdownTimeoutMs: number;
}): Promise<void> => {
  if (await waitForServerShutdown(attached, shutdownTimeoutMs)) return;
  await stopRuntimeProcess({
    pid: attached.handshake.pid,
    timeoutMs: shutdownTimeoutMs,
    isOwned: async () => {
      return (
        processIdentity !== null &&
        runtimeProcessIdentity(attached.handshake.pid) === processIdentity
      );
    },
  });
};

export const retireUnavailablePreview = async ({
  attached,
  clientVersion,
  shutdownTimeoutMs,
}: {
  attached: AttachedServer;
  clientVersion: string;
  shutdownTimeoutMs: number;
}): Promise<RuntimeRetirement> => {
  const serverVersion = attached.handshake.rivetVersion;
  if (!serverVersion || isNewerVersion(serverVersion, clientVersion))
    return { outcome: 'kept' };
  try {
    const processIdentity = runtimeProcessIdentity(attached.handshake.pid);
    const upgrade = await requestServer(attached, '/api/cli/upgrade', {
      method: 'POST',
      body: { clientVersion, requireIdle: true },
    });
    const parsed = upgradeSchema.parse(upgrade.body);
    if (upgrade.status !== 200 || parsed.stopping !== true)
      return { outcome: 'kept' };
    await awaitOwnedRuntimeShutdown({
      attached,
      processIdentity,
      shutdownTimeoutMs,
    });
    return { outcome: 'retired', restartArgs: parsed.restartArgs };
  } catch {
    return { outcome: 'kept' };
  }
};

export const prepareRuntimeUpgrade = async ({
  attached,
  io,
  shutdownTimeoutMs,
}: {
  attached: AttachedServer;
  io: CliIO;
  shutdownTimeoutMs: number;
}): Promise<RuntimeUpgradeOutcome> => {
  const info = serverVersionInfo(attached.handshake);
  if (!info.staleServer) return { outcome: 'attach' };
  const fail = (reason: string, message: string): RuntimeUpgradeOutcome => ({
    outcome: 'failed',
    reason,
    message,
  });
  try {
    const processIdentity = runtimeProcessIdentity(attached.handshake.pid);
    const response = await requestServer(attached, '/api/health');
    const health = healthSchema.safeParse(response.body);
    if (
      response.status !== 200 ||
      !health.success ||
      health.data.pid !== attached.handshake.pid ||
      fs.realpathSync(health.data.projectPath) !==
        fs.realpathSync(attached.handshake.projectPath) ||
      health.data.rivetVersion !== attached.handshake.rivetVersion
    )
      return fail(
        'server_identity_mismatch',
        'The outdated project server could not verify its identity. It was not stopped.',
      );
    const status = await requestServer(attached, '/api/cli/status').catch(
      () => null,
    );
    if (status?.status === 401 || status?.status === 403)
      return fail(
        'server_access_denied',
        'The outdated project server denied access. It was not stopped.',
      );
    const snapshot = status?.status === 200 ? status.body : null;
    let upgrade = await requestServer(attached, '/api/cli/upgrade', {
      method: 'POST',
      body: { clientVersion: info.cliVersion },
    });
    let parsed = upgradeSchema.parse(upgrade.body);
    const fallbackArgs = [
      '--project',
      attached.handshake.projectPath,
      '--rivet-port',
      String(attached.handshake.rivetPort),
    ];
    if (health.data.framework)
      fallbackArgs.push('--framework', health.data.framework);
    const devServer = devServerSchema.safeParse(snapshot);
    if (
      devServer.success &&
      devServer.data.devServerHealth?.ownership === 'external' &&
      devServer.data.devServerHealth.port
    )
      fallbackArgs.push(
        '--user-port',
        String(devServer.data.devServerHealth.port),
      );
    if (
      upgrade.status === 404 ||
      (upgrade.status === 409 && INTERRUPTIBLE_REASONS.has(parsed.reason ?? ''))
    ) {
      upgrade = await requestServer(attached, '/api/cli/shutdown', {
        method: 'POST',
        body: {},
      });
      parsed = upgradeSchema.parse(upgrade.body);
    }
    if (upgrade.status !== 200 || parsed.stopping !== true)
      return fail(
        parsed.reason ?? 'server_upgrade_required',
        parsed.error ??
          'The outdated project server could not be restarted. Inspect its log and retry `rivet open`.',
      );
    const interruptedWork =
      classifyRuntimeActivity(snapshot) !== 'idle'
        ? recordRuntimeInterruption({ attached, snapshot })
        : undefined;
    if (interruptedWork)
      io.writeProgress(
        `${interruptedWork.message} Recovery details: ${interruptedWork.receiptPath}`,
      );
    await awaitOwnedRuntimeShutdown({
      attached,
      processIdentity,
      shutdownTimeoutMs,
    });
    io.writeProgress(`Upgrading project server to rivet v${info.cliVersion}…`);
    return {
      outcome: 'spawn',
      restartArgs: parsed.restartArgs ?? fallbackArgs,
      ...(interruptedWork ? { interruptedWork } : {}),
    };
  } catch (error) {
    return fail('server_upgrade_required', errorMessage(error));
  }
};
